mapper.update:
UPDATE tb_message
SET status = #{status}, update_time = NOW()
WHERE conversation_id = #{conversationId}
  AND to_user_id = #{userId}
  AND status = 0

mapper.select:
SELECT COUNT(*)
FROM tb_message
WHERE conversation_id = #{conversationId}
  AND to_user_id = #{userId}
  AND status = 0
  AND is_deleted_by_receiver = 0
